"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["79201"],{44474(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.etapa_referenciada_por_desempate","status":422,"titulo":"A etapa \xe9 referenciada por um crit\xe9rio de desempate e n\xe3o pode ser removida sem antes reconfigurar o desempate"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.etapa_referenciada_por_desempate","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["O processo j\xe1 tem um ou mais crit\xe9rios de desempate definidos com o c\xf3digo\\n`DESEMPATE_MAIOR_NOTA_ETAPA`, e o novo corpo do pedido de defini\xe7\xe3o de etapas omite\\numa etapa que um desses crit\xe9rios referencia (`etapaRef`). Substituir a\\nlista de etapas sem revalidar deixaria o crit\xe9rio apontando para uma etapa\\nremovida \u2014 um desempate inexecut\xe1vel, que s\xf3 apareceria no momento de\\ncalcular o resultado.","A confer\xeancia (INV-B6) roda como parte da pr\xf3pria substitui\xe7\xe3o das etapas \u2014\\npor isso rejeita a troca em vez de silenciosamente invalidar o desempate\\nexistente: quem administra o processo reconfigura o desempate primeiro,\\ndepois redefine as etapas.","\xc9 sequencial: roda depois de\\n[`ordem_etapa_duplicada`](/erros/uniplus.selecao.processo_seletivo.ordem_etapa_duplicada)\\ne\\n[`nenhuma_etapa_compoe_nota`](/erros/uniplus.selecao.processo_seletivo.nenhuma_etapa_compoe_nota)\\nj\xe1 terem passado, e antes de\\n[`etapa_referenciada_por_classificacao`](/erros/uniplus.selecao.processo_seletivo.etapa_referenciada_por_classificacao)\\n(a mesma prote\xe7\xe3o, para a classifica\xe7\xe3o) \u2014 n\xe3o acumula com nenhuma delas; a\\nprimeira que falhar interrompe a substitui\xe7\xe3o."],"comoResolver":["O gatilho mais comum n\xe3o \xe9 uma remo\xe7\xe3o intencional: o `PUT` de etapas\\nreconcilia a lista inteira **pelo campo `id`** de cada item \u2014 uma etapa\\nexistente reenviada sem `id` (ou com um `id` que n\xe3o bate com nenhuma\\netapa atual) n\xe3o \xe9 reconhecida como a mesma etapa, e vira uma etapa nova,\\ncom identificador novo, mesmo que os demais campos sejam id\xeanticos. Se a\\ninten\xe7\xe3o era s\xf3 editar outro campo de uma etapa que o desempate j\xe1\\nreferencia (peso, nota m\xednima, nome), confira que o `id` dela foi ecoado no\\ncorpo do pedido \u2014 sem alter\xe1-lo, o `etapaRef` continua resolvendo, e a mudan\xe7a\\nsegue sem precisar tocar no desempate.","Se a remo\xe7\xe3o da etapa \xe9 de fato intencional, reconfigure o crit\xe9rio de\\ndesempate antes \u2014 redirecione-o para outra etapa ou troque o c\xf3digo do\\ncrit\xe9rio. S\xf3 ent\xe3o redefina as etapas."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);